SELECT sbi.id, sbi.code, sbi.approve_status AS approveStatus, sbi.approve_user_id AS approveUserId, sbi.approve_user_name AS approveUserName, sbi.approve_time AS approveTime, sbi.invalid_status AS invalidStatus, sbi.invalid_remark AS invalidRemark, sbi.invalid_time AS invalidTime, sbi.back_date AS backDate, sbi.source_id AS sourceId, sbi.source_code AS sourceCode, sbi.source_type AS sourceType, sbi.user_id AS userId, sbi.user_name AS userName, sbi.dept_id AS deptId, sbi.warehouse_id AS warehouseId, w.name AS warehouseName, sbi.org_id AS orgId, sbi.org_name AS orgName, sbi.remark, sbi.exec_status AS execStatus, sbi.create_time AS createTime, sbi.create_user_name AS createUserName, sbd.id AS detailId, sbd.sku_no AS skuNo, sbd.sku_id AS skuId, sbd.product_name AS productName, sbd.qty, sbd.remark AS detailRemark FROM sample_back_info sbi LEFT JOIN sample_back_detail sbd ON sbd.main_id = sbi.id AND sbi.is_deleted = false LEFT JOIN warehouse w ON w.id = sbi.warehouse_id AND w.is_deleted = false WHERE
${params.sqlMap.default}
1=1
AND sbd.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sbi.create_time DESC, sbd.id ASC

SELECT sbi.id, sbi.code, sbi.approve_status AS approveStatus, sbi.approve_user_id AS approveUserId, sbi.approve_user_name AS approveUserName, sbi.approve_time AS approveTime, sbi.invalid_status AS invalidStatus, sbi.invalid_remark AS invalidRemark, sbi.invalid_time AS invalidTime, sbi.back_date AS backDate, sbi.source_id AS sourceId, sbi.source_code AS sourceCode, sbi.source_type AS sourceType, sbi.user_id AS userId, sbi.user_name AS userName, sbi.dept_id AS deptId, sbi.warehouse_id AS warehouseId, w.name AS warehouseName, sbi.org_id AS orgId, sbi.org_name AS orgName, sbi.remark, sbi.exec_status AS execStatus, sbi.create_time AS createTime, sbi.create_user_name AS createUserName, sbd.id AS detailId, sbd.sku_no AS skuNo, sbd.sku_id AS skuId, sbd.product_name AS productName, sbd.qty, sbd.remark AS detailRemark FROM sample_back_info sbi LEFT JOIN sample_back_detail sbd ON sbd.main_id = sbi.id AND sbi.is_deleted = false LEFT JOIN warehouse w ON w.id = sbi.warehouse_id AND w.is_deleted = false WHERE
${params.sqlMap.default}
1=1
AND sbd.is_deleted = false
AND sbi.id in
#{item}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sbi.create_time DESC, sbd.id ASC

SELECT approve_status AS tabFlag, count(*) AS count FROM sample_back_info sbi WHERE is_deleted=FALSE
${params.permissionSql}
GROUP BY approve_status
